<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Store | Reny Renteria</title>
    <link rel="icon" href="data:image/svg+xml,%3Csvg viewBox='0 0 32 32' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='32' height='32' fill='%230f0e0c'/%3E%3Ctext x='16' y='21' text-anchor='middle' fill='%23d8bc7b' font-family='Georgia' font-size='11'%3ERR%3C/text%3E%3C/svg%3E">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;500&display=swap" rel="stylesheet">
    <style>
        :root {
            --paper: #f6f1e8;
            --surface: #fffcf6;
            --ink: #11100e;
            --muted: #776f64;
            --line: #ded3c2;
            --gold: #a9833e;
            --gold-soft: #e4cc94;
            --wine: #421216;
            --black: #0f0e0c;
            --sidebar: 274px;
            --shadow: 0 22px 60px rgba(28, 21, 13, 0.12);
        }

        * {
            box-sizing: border-box;
        }

        html {
            background: var(--paper);
            color: var(--ink);
        }

        body {
            min-height: 100vh;
            margin: 0;
            background: var(--paper);
            color: var(--ink);
            font-family: "DM Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            letter-spacing: 0;
        }

        body.is-locked {
            overflow: hidden;
        }

        a {
            color: inherit;
            text-decoration: none;
        }

        button,
        input {
            color: inherit;
            font: inherit;
        }

        button {
            cursor: pointer;
        }

        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            margin: -1px;
            padding: 0;
            overflow: hidden;
            border: 0;
            clip: rect(0, 0, 0, 0);
            clip-path: inset(50%);
            white-space: nowrap;
        }

        .shop-shell {
            display: grid;
            grid-template-columns: var(--sidebar) minmax(0, 1fr);
            min-height: 100vh;
        }

        .sidebar {
            position: sticky;
            top: 0;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            height: 100vh;
            padding: 32px 36px 34px;
            border-right: 1px solid var(--line);
            background: rgba(255, 252, 246, 0.78);
        }

        .brand {
            display: inline-grid;
            gap: 7px;
            width: fit-content;
        }

        .brand strong {
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 32px;
            font-weight: 500;
            line-height: 0.88;
        }

        .brand span {
            color: var(--gold);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.22em;
            text-transform: uppercase;
        }

        .tabs {
            display: grid;
            gap: 18px;
            margin-top: 58px;
        }

        .tab {
            position: relative;
            display: grid;
            grid-template-columns: 28px minmax(0, 1fr);
            align-items: center;
            min-height: 34px;
            color: var(--muted);
            font-size: 14px;
            font-weight: 500;
            gap: 18px;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .tab svg {
            width: 22px;
            height: 22px;
            stroke-width: 1.8;
        }

        .tab:hover,
        .tab:focus-visible,
        .tab.is-active {
            color: var(--gold);
        }

        .tab.is-active::before {
            content: "";
            position: absolute;
            top: 4px;
            left: -30px;
            width: 4px;
            height: 26px;
            border-radius: 999px;
            background: var(--gold);
        }

        .member-card {
            display: grid;
            grid-template-columns: 34px minmax(0, 1fr);
            align-items: center;
            width: 164px;
            padding: 10px 12px;
            border: 1px solid #eee5d8;
            border-radius: 4px;
            background: rgba(255, 255, 255, 0.72);
            box-shadow: 0 8px 18px rgba(28, 20, 12, 0.05);
            gap: 10px;
        }

        .member-avatar {
            display: grid;
            place-items: center;
            width: 32px;
            aspect-ratio: 1;
            border-radius: 6px;
            background: var(--black);
            color: var(--gold-soft);
            font-size: 11px;
            font-weight: 500;
        }

        .member-card strong,
        .member-card span {
            display: block;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .member-card strong {
            font-size: 10px;
            line-height: 1.1;
        }

        .member-card span {
            margin-top: 2px;
            color: var(--muted);
            font-size: 9px;
            font-weight: 500;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .main {
            min-width: 0;
            padding: 48px 6vw 82px 48px;
        }

        .mobile-header,
        .mobile-bottom-nav {
            display: none;
        }

        .topline {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 20px;
            margin-bottom: 24px;
        }

        .topline h1 {
            margin: 0;
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 56px;
            font-weight: 400;
            line-height: 0.94;
        }

        .actions {
            display: flex;
            align-items: center;
            justify-content: flex-end;
            flex-wrap: wrap;
            gap: 10px;
        }

        .segmented {
            display: inline-grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            overflow: hidden;
            min-height: 38px;
            border: 1px solid var(--line);
            border-radius: 999px;
            background: var(--surface);
        }

        .segmented button {
            min-width: 62px;
            border: 0;
            background: transparent;
            color: var(--muted);
            font-size: 11px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .segmented button.is-active {
            background: var(--black);
            color: var(--gold-soft);
        }

        .bag-button,
        .button {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-height: 40px;
            padding: 0 16px;
            border: 1px solid var(--black);
            border-radius: 999px;
            background: var(--black);
            color: #fff;
            gap: 8px;
            font-size: 11px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
            transition: transform 160ms ease, background 160ms ease, color 160ms ease;
        }

        .button:hover,
        .button:focus-visible,
        .bag-button:hover,
        .bag-button:focus-visible {
            transform: translateY(-1px);
        }

        .button.gold {
            border-color: var(--gold-soft);
            background: var(--gold-soft);
            color: var(--black);
        }

        .button.ghost {
            border-color: rgba(17, 16, 14, 0.2);
            background: transparent;
            color: var(--ink);
        }

        .button.light {
            border-color: rgba(255, 255, 255, 0.34);
            background: rgba(255, 255, 255, 0.08);
            color: #fff;
        }

        .bag-button span {
            color: var(--gold-soft);
        }

        .feature {
            position: relative;
            display: grid;
            grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.62fr);
            overflow: hidden;
            min-height: 610px;
            border: 1px solid rgba(169, 131, 62, 0.28);
            border-radius: 8px;
            background: var(--black);
            color: #fff;
            box-shadow: var(--shadow);
        }

        .feature-image {
            position: relative;
            min-height: 610px;
            overflow: hidden;
            background: #171411;
        }

        .feature-image img {
            width: 100%;
            height: 100%;
            display: block;
            object-fit: cover;
        }

        .feature-image::after {
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(90deg, rgba(15, 14, 12, 0.08), rgba(15, 14, 12, 0.12) 62%, rgba(15, 14, 12, 0.6)),
                linear-gradient(180deg, transparent 55%, rgba(15, 14, 12, 0.4));
            pointer-events: none;
        }

        .feature-copy {
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            padding: 42px;
            border-left: 1px solid rgba(228, 204, 148, 0.22);
        }

        .eyebrow {
            width: fit-content;
            padding: 7px 10px;
            border: 1px solid rgba(228, 204, 148, 0.42);
            border-radius: 999px;
            color: var(--gold-soft);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .feature h2 {
            margin: 20px 0 0;
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 54px;
            font-weight: 400;
            line-height: 0.92;
        }

        .feature-price {
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            gap: 18px;
            margin-top: 28px;
        }

        .feature-price strong {
            display: block;
            font-size: 34px;
            line-height: 1;
        }

        .feature-price span {
            display: block;
            margin-top: 7px;
            color: rgba(255, 255, 255, 0.56);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .drop-strip {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            margin-top: 32px;
            border: 1px solid rgba(228, 204, 148, 0.22);
            border-radius: 6px;
        }

        .drop-strip div {
            min-width: 0;
            padding: 15px;
            border-right: 1px solid rgba(228, 204, 148, 0.18);
        }

        .drop-strip div:last-child {
            border-right: 0;
        }

        .drop-strip strong,
        .drop-strip span {
            display: block;
        }

        .drop-strip strong {
            color: #fff;
            font-size: 19px;
            line-height: 1;
        }

        .drop-strip span {
            margin-top: 7px;
            color: rgba(255, 255, 255, 0.54);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .events {
            margin-top: 22px;
        }

        .section-title {
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            gap: 18px;
            margin-bottom: 14px;
        }

        .section-title h2 {
            margin: 0;
            font-size: 34px;
            font-weight: 300;
            line-height: 1;
        }

        .section-title span {
            color: var(--muted);
            font-size: 11px;
            font-weight: 500;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .event-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 18px;
        }

        .event-card {
            position: relative;
            display: grid;
            overflow: hidden;
            padding: 0;
            border: 1px solid var(--line);
            border-radius: 8px;
            background: var(--surface);
            color: var(--ink);
            box-shadow: 0 16px 44px rgba(28, 21, 13, 0.08);
        }

        .event-photo {
            display: block;
            width: 100%;
            aspect-ratio: 4 / 5;
            object-fit: cover;
            background: var(--black);
        }

        .event-content {
            display: grid;
            min-height: 182px;
            padding: 22px;
            gap: 16px;
        }

        .event-kicker {
            color: var(--gold);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.14em;
            text-transform: uppercase;
        }

        .event-content h3 {
            margin: 0;
            font-size: 27px;
            font-weight: 400;
            line-height: 1;
        }

        .event-meta {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        .event-meta span {
            display: inline-flex;
            align-items: center;
            min-height: 28px;
            padding: 0 9px;
            border: 1px solid var(--line);
            border-radius: 999px;
            color: var(--muted);
            font-size: 11px;
            font-weight: 500;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .event-meta b {
            margin-right: 5px;
            color: var(--gold);
            font-weight: 500;
        }

        .event-actions {
            display: flex;
            margin-top: auto;
        }

        .event-actions .button {
            width: 100%;
            justify-content: center;
        }

        .market {
            display: flex;
            align-items: center;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 16px;
            margin: 36px 0 18px;
        }

        .market h2 {
            margin: 0;
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 35px;
            font-weight: 400;
        }

        .filters {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        .filter {
            min-height: 34px;
            padding: 0 12px;
            border: 1px solid var(--line);
            border-radius: 999px;
            background: var(--surface);
            color: var(--muted);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .filter.is-active {
            border-color: var(--black);
            background: var(--black);
            color: #fff;
        }

        .product-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 18px;
        }

        .product-card {
            position: relative;
            overflow: hidden;
            min-height: 498px;
            border: 1px solid var(--line);
            border-radius: 8px;
            background: var(--surface);
            box-shadow: 0 16px 44px rgba(28, 21, 13, 0.08);
        }

        .product-button {
            display: grid;
            grid-template-rows: minmax(310px, 1fr) auto;
            width: 100%;
            min-height: 498px;
            padding: 0;
            border: 0;
            background: transparent;
            text-align: left;
        }

        .visual {
            position: relative;
            overflow: hidden;
            min-height: 330px;
            background: #171411;
        }

        .visual::before,
        .visual::after {
            content: "";
            position: absolute;
        }

        .visual.hero-crop {
            background-image: var(--hero-image);
            background-position: center;
            background-size: cover;
        }

        .visual.hero-crop::after {
            inset: 0;
            background: linear-gradient(180deg, transparent 52%, rgba(15, 14, 12, 0.52));
        }

        .visual.album {
            background:
                radial-gradient(circle at 66% 30%, rgba(228, 204, 148, 0.26), transparent 28%),
                linear-gradient(135deg, #f6ead8, #c6a96d 54%, #171411);
        }

        .visual.album::before {
            top: 48px;
            left: 50%;
            width: 178px;
            height: 230px;
            border: 1px solid rgba(17, 16, 14, 0.22);
            transform: translateX(-50%) rotate(-3deg);
            background:
                linear-gradient(135deg, rgba(255, 255, 255, 0.52), transparent 42%),
                linear-gradient(180deg, #fff8ef, #171411);
            box-shadow: 0 24px 60px rgba(17, 16, 14, 0.24);
        }

        .visual.album::after {
            top: 112px;
            left: 50%;
            width: 96px;
            height: 96px;
            border: 1px solid rgba(228, 204, 148, 0.7);
            border-radius: 999px;
            transform: translateX(-50%);
            background: rgba(17, 16, 14, 0.72);
        }

        .visual.pack {
            background:
                linear-gradient(145deg, rgba(228, 204, 148, 0.22), transparent 36%),
                linear-gradient(180deg, #281216, #0f0e0c);
        }

        .visual.pack::before,
        .visual.pack::after {
            top: 62px;
            width: 142px;
            height: 198px;
            border: 1px solid rgba(228, 204, 148, 0.42);
            background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.01));
            box-shadow: 0 22px 50px rgba(0, 0, 0, 0.34);
        }

        .visual.pack::before {
            left: calc(50% - 104px);
            transform: rotate(-7deg);
        }

        .visual.pack::after {
            left: calc(50% - 26px);
            transform: rotate(7deg);
        }

        .visual.pass {
            background:
                radial-gradient(circle at 50% 8%, rgba(228, 204, 148, 0.3), transparent 28%),
                linear-gradient(180deg, #11100e, #2a2015);
        }

        .visual.pass::before {
            top: 86px;
            left: 50%;
            width: 230px;
            height: 142px;
            border: 1px solid rgba(228, 204, 148, 0.54);
            border-radius: 12px;
            transform: translateX(-50%) rotate(-8deg);
            background:
                linear-gradient(120deg, rgba(255, 255, 255, 0.18), transparent 38%),
                #11100e;
            box-shadow: 0 24px 60px rgba(0, 0, 0, 0.36);
        }

        .visual.pass::after {
            top: 126px;
            left: 50%;
            width: 72px;
            height: 72px;
            border: 1px solid rgba(228, 204, 148, 0.7);
            border-radius: 999px;
            transform: translateX(-50%);
        }

        .visual.merch {
            background:
                radial-gradient(circle at 50% 22%, rgba(228, 204, 148, 0.24), transparent 28%),
                linear-gradient(180deg, #e9dfd1, #b9a582);
        }

        .visual.merch::before {
            top: 54px;
            left: 50%;
            width: 190px;
            height: 240px;
            border-radius: 40px 40px 18px 18px;
            transform: translateX(-50%);
            background:
                radial-gradient(circle at 50% 30%, rgba(17, 16, 14, 0.16) 0 28px, transparent 29px),
                linear-gradient(180deg, #191716, #0f0e0c);
            box-shadow: 0 24px 54px rgba(17, 16, 14, 0.24);
        }

        .visual.print {
            background:
                linear-gradient(135deg, rgba(228, 204, 148, 0.24), transparent 38%),
                linear-gradient(180deg, #f8f1e6, #211613);
        }

        .visual.print::before {
            top: 44px;
            left: 50%;
            width: 192px;
            height: 248px;
            border: 12px solid #fffaf2;
            transform: translateX(-50%) rotate(4deg);
            background: linear-gradient(180deg, #191716 0 52%, #c4a567 52% 100%);
            box-shadow: 0 22px 56px rgba(17, 16, 14, 0.26);
        }

        .product-meta {
            display: grid;
            align-content: end;
            min-height: 168px;
            padding: 22px;
            gap: 15px;
        }

        .product-line {
            display: flex;
            align-items: start;
            justify-content: space-between;
            gap: 14px;
        }

        .product-line h3 {
            max-width: 210px;
            margin: 0;
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 27px;
            font-weight: 400;
            line-height: 1;
        }

        .product-line strong {
            white-space: nowrap;
            font-size: 19px;
            line-height: 1;
        }

        .chips {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
        }

        .chip {
            display: inline-flex;
            align-items: center;
            min-height: 24px;
            padding: 0 8px;
            border: 1px solid rgba(17, 16, 14, 0.14);
            border-radius: 999px;
            color: var(--muted);
            font-size: 9px;
            font-weight: 500;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .chip.gold {
            border-color: rgba(169, 131, 62, 0.34);
            color: var(--gold);
        }

        .modal-layer {
            position: fixed;
            inset: 0;
            z-index: 60;
            display: grid;
            place-items: center;
            padding: 18px;
            background: rgba(15, 14, 12, 0.54);
            backdrop-filter: blur(10px);
        }

        .modal-layer[hidden] {
            display: none;
        }

        .dialog {
            width: min(920px, 100%);
            max-height: min(760px, calc(100vh - 36px));
            overflow: auto;
            border: 1px solid rgba(228, 204, 148, 0.28);
            border-radius: 10px;
            background: var(--surface);
            box-shadow: 0 30px 90px rgba(0, 0, 0, 0.34);
        }

        .dialog-head {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            padding: 22px 24px;
            border-bottom: 1px solid var(--line);
        }

        .dialog-head h2 {
            margin: 0;
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 34px;
            font-weight: 400;
            line-height: 1;
        }

        .icon-button {
            display: grid;
            place-items: center;
            width: 40px;
            aspect-ratio: 1;
            border: 1px solid var(--line);
            border-radius: 999px;
            background: #fff;
            color: var(--ink);
            font-size: 22px;
            line-height: 1;
        }

        .product-detail {
            display: grid;
            grid-template-columns: minmax(0, 1fr) minmax(280px, 0.68fr);
            gap: 22px;
            padding: 24px;
        }

        .detail-visual {
            min-height: 420px;
            border-radius: 8px;
        }

        .detail-copy {
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            gap: 22px;
        }

        .detail-copy p {
            margin: 0;
            color: var(--muted);
            font-size: 15px;
            font-weight: 500;
            line-height: 1.55;
        }

        .detail-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 10px;
        }

        .detail-grid div {
            min-height: 70px;
            padding: 12px;
            border: 1px solid var(--line);
            border-radius: 6px;
            background: #fff;
        }

        .detail-grid strong,
        .detail-grid span {
            display: block;
        }

        .detail-grid strong {
            font-size: 16px;
            line-height: 1;
        }

        .detail-grid span {
            margin-top: 7px;
            color: var(--muted);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .checkout-grid {
            display: grid;
            grid-template-columns: minmax(0, 0.9fr) minmax(300px, 0.7fr);
            gap: 22px;
            padding: 24px;
        }

        .checkout-panel {
            padding: 20px;
            border: 1px solid var(--line);
            border-radius: 8px;
            background: #fff;
        }

        .checkout-panel h3 {
            margin: 0 0 16px;
            font-size: 13px;
            font-weight: 500;
            letter-spacing: 0.14em;
            text-transform: uppercase;
        }

        .bag-list {
            display: grid;
            gap: 12px;
        }

        .bag-item {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
            padding-bottom: 12px;
            border-bottom: 1px solid var(--line);
            color: var(--muted);
            font-size: 13px;
            font-weight: 500;
        }

        .bag-item strong {
            color: var(--ink);
        }

        .payments {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 10px;
        }

        .payments button {
            min-height: 46px;
            border: 1px solid var(--line);
            border-radius: 999px;
            background: #fff;
            color: var(--muted);
            font-size: 11px;
            font-weight: 500;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .payments button.is-active {
            border-color: var(--black);
            background: var(--black);
            color: #fff;
        }

        .email {
            width: 100%;
            min-height: 46px;
            margin-top: 14px;
            padding: 0 14px;
            border: 1px solid var(--line);
            border-radius: 999px;
            background: #fff;
            outline: 0;
        }

        .total-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            margin-top: 18px;
            padding-top: 18px;
            border-top: 1px solid var(--line);
            font-size: 24px;
            font-weight: 500;
        }

        .certificate-card {
            display: grid;
            gap: 24px;
            margin: 24px;
            padding: 34px;
            border: 1px solid var(--gold);
            border-radius: 8px;
            background:
                linear-gradient(135deg, rgba(228, 204, 148, 0.16), transparent 42%),
                #11100e;
            color: #fff;
        }

        .certificate-card h3 {
            margin: 0;
            font-family: "DM Sans", ui-sans-serif, system-ui, sans-serif;
            font-size: 43px;
            font-weight: 400;
            line-height: 0.96;
        }

        .certificate-card p {
            margin: 0;
            max-width: 540px;
            color: rgba(255, 255, 255, 0.7);
            font-size: 15px;
            font-weight: 500;
            line-height: 1.5;
        }

        .certificate-meta {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 12px;
        }

        .certificate-meta div {
            padding: 14px;
            border: 1px solid rgba(228, 204, 148, 0.28);
            border-radius: 6px;
        }

        .certificate-meta strong,
        .certificate-meta span {
            display: block;
        }

        .certificate-meta strong {
            color: var(--gold-soft);
            font-size: 18px;
            line-height: 1;
        }

        .certificate-meta span {
            margin-top: 7px;
            color: rgba(255, 255, 255, 0.56);
            font-size: 10px;
            font-weight: 500;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .toast {
            position: fixed;
            right: 24px;
            bottom: 24px;
            z-index: 80;
            max-width: 320px;
            padding: 14px 16px;
            border: 1px solid rgba(228, 204, 148, 0.36);
            border-radius: 6px;
            transform: translateY(16px);
            background: #11100e;
            color: #fff;
            opacity: 0;
            pointer-events: none;
            transition: opacity 180ms ease, transform 180ms ease;
            font-size: 13px;
            font-weight: 500;
            line-height: 1.35;
        }

        .toast.is-visible {
            transform: translateY(0);
            opacity: 1;
        }

        @media (max-width: 1180px) {
            .main {
                padding-right: 36px;
            }

            .feature,
            .event-grid {
                grid-template-columns: 1fr;
            }

            .feature-copy {
                border-top: 1px solid rgba(228, 204, 148, 0.22);
                border-left: 0;
            }

            .product-grid {
                grid-template-columns: repeat(2, minmax(0, 1fr));
            }
        }

        @media (max-width: 860px) {
            .shop-shell {
                display: block;
            }

            .sidebar {
                display: none;
            }

            .main {
                padding: 12px 14px calc(104px + env(safe-area-inset-bottom));
            }

            .mobile-header {
                display: flex;
                align-items: center;
                justify-content: center;
                min-height: 78px;
            }

            .mobile-bottom-nav {
                position: fixed;
                right: 0;
                bottom: 0;
                left: 0;
                z-index: 20;
                display: grid;
                grid-template-columns: repeat(5, minmax(0, 1fr));
                height: calc(80px + env(safe-area-inset-bottom));
                padding-bottom: env(safe-area-inset-bottom);
                border-top: 1px solid rgba(169, 131, 62, 0.34);
                background: rgba(255, 252, 246, 0.96);
                box-shadow: 0 -14px 30px rgba(28, 20, 12, 0.12);
                backdrop-filter: blur(12px);
            }

            .mobile-bottom-nav a {
                display: grid;
                place-items: center;
                min-width: 0;
                border-right: 1px solid rgba(169, 131, 62, 0.26);
                color: var(--muted);
            }

            .mobile-bottom-nav a:last-child {
                border-right: 0;
            }

            .mobile-bottom-nav a.is-active {
                background: rgba(169, 131, 62, 0.08);
                color: var(--gold);
            }

            .mobile-bottom-nav svg {
                width: 28px;
                height: 28px;
                stroke-width: 1.85;
            }

            .topline {
                align-items: flex-start;
                flex-direction: column;
                margin-bottom: 18px;
            }

            .topline h1 {
                font-size: 46px;
            }

            .actions {
                justify-content: flex-start;
            }

            .feature {
                min-height: 0;
                grid-template-columns: 1fr;
            }

            .feature-image {
                min-height: 420px;
            }

            .feature-copy {
                padding: 28px;
            }

            .feature h2 {
                font-size: 42px;
            }

            .market {
                align-items: flex-start;
                margin: 20px 0 14px;
            }

            .events {
                margin-top: 18px;
            }

            .section-title {
                align-items: flex-start;
                flex-direction: column;
                gap: 7px;
            }

            .event-card {
                min-height: 0;
            }

            .market h2 {
                font-size: 30px;
            }

            .filters {
                width: 100%;
                flex-wrap: nowrap;
                overflow-x: auto;
                padding-bottom: 2px;
                scrollbar-width: none;
            }

            .filters::-webkit-scrollbar {
                display: none;
            }

            .filter {
                flex: 0 0 auto;
            }

            .product-grid,
            .product-detail,
            .checkout-grid {
                grid-template-columns: 1fr;
            }

            .product-card,
            .product-button {
                min-height: 520px;
            }

            .visual {
                min-height: 352px;
            }

            .detail-visual {
                min-height: 360px;
            }
        }

        @media (max-width: 520px) {
            .mobile-header {
                min-height: 58px;
            }

            .mobile-bottom-nav {
                height: calc(72px + env(safe-area-inset-bottom));
            }

            .mobile-bottom-nav svg {
                width: 25px;
                height: 25px;
            }

            .brand strong {
                font-size: 28px;
            }

            .topline h1 {
                font-size: 34px;
            }

            .actions {
                width: 100%;
            }

            .segmented {
                flex: 1 1 164px;
            }

            .bag-button {
                flex: 0 0 auto;
            }

            .feature {
                min-height: 254px;
            }

            .feature-image {
                min-height: 254px;
            }

            .feature-image::after {
                background:
                    linear-gradient(180deg, rgba(15, 14, 12, 0.04) 18%, rgba(15, 14, 12, 0.18) 48%, rgba(15, 14, 12, 0.86)),
                    linear-gradient(90deg, rgba(15, 14, 12, 0.08), rgba(15, 14, 12, 0.4));
            }

            .feature-copy {
                position: absolute;
                inset: auto 0 0;
                padding: 14px;
                border-top: 0;
                background: linear-gradient(180deg, transparent, rgba(15, 14, 12, 0.9) 34%, rgba(15, 14, 12, 0.98));
            }

            .feature h2 {
                margin-top: 8px;
                font-size: 28px;
            }

            .drop-strip {
                margin-top: 10px;
            }

            .feature-price {
                margin-top: 12px;
            }

            .feature-price {
                align-items: stretch;
                flex-direction: row;
            }

            .feature-price .button {
                min-width: 132px;
            }

            .certificate-meta {
                grid-template-columns: 1fr;
            }

            .drop-strip div {
                padding: 12px 10px;
                border-right: 1px solid rgba(228, 204, 148, 0.18);
                border-bottom: 0;
            }

            .drop-strip div:last-child {
                border-right: 0;
            }

            .drop-strip strong {
                font-size: 16px;
            }

            .drop-strip span {
                font-size: 9px;
            }

            .market {
                align-items: flex-start;
                flex-direction: column;
                margin-top: 12px;
                margin-bottom: 18px;
            }

            .section-title h2,
            .event-content h3 {
                font-size: 29px;
            }

            .event-card {
                min-height: 318px;
            }

            .event-meta span {
                min-height: 26px;
                padding: 0 8px;
                font-size: 10px;
            }

            .product-card,
            .product-button {
                min-height: 446px;
            }

            .visual {
                min-height: 292px;
            }

            .product-meta {
                padding: 19px;
            }

            .product-line h3 {
                font-size: 24px;
            }

            .payments {
                grid-template-columns: 1fr;
            }

            .dialog-head h2 {
                font-size: 28px;
            }

            .certificate-card {
                margin: 18px;
                padding: 24px;
            }

            .certificate-card h3 {
                font-size: 34px;
            }

            .toast {
                right: 14px;
                bottom: calc(92px + env(safe-area-inset-bottom));
                left: 14px;
            }
        }
    </style>
</head>
<body>
    <div class="shop-shell" style="--hero-image: url('data:image/jpeg;base64,');">
        <aside class="sidebar" aria-label="Main navigation">
            <div>
                <a class="brand" href="/">
                    <strong>Reny<br>Renteria</strong>
                    <span>El Estudio</span>
                </a>
                <nav class="tabs" aria-label="Primary">
                    <a class="tab" href="/"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M9 18V5l12-2v13"></path><circle cx="6" cy="18" r="3"></circle><circle cx="18" cy="16" r="3"></circle></svg><span>Music</span></a>
                    <a class="tab" href="/videos"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M15 10l5 3-5 3v-6Z"></path><rect x="3" y="5" width="18" height="14" rx="2"></rect></svg><span>Videos</span></a>
                    <a class="tab" href="/photos"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="5" width="18" height="14" rx="2"></rect><circle cx="8" cy="10" r="2"></circle><path d="m21 15-5-5L5 19"></path></svg><span>Photos</span></a>
                    <a class="tab" href="/community"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v8Z"></path></svg><span>Community</span></a>
                    <a class="tab is-active" href="/store" aria-current="page"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4H6Z"></path><path d="M3 6h18"></path><path d="M16 10a4 4 0 0 1-8 0"></path></svg><span>Store</span></a>
                </nav>
            </div>
            <div class="member-card" aria-label="Profile preview">
                <div class="member-avatar">RR</div>
                <div>
                    <strong>Royal Tier</strong>
                    <span id="tierLabel">Member</span>
                </div>
            </div>
        </aside>

        <main class="main">
            <header class="mobile-header">
                <a class="brand" href="/">
                    <strong>Reny<br>Renteria</strong>
                    <span>Store</span>
                </a>
            </header>

            <section class="topline" aria-label="Store controls">
                <h1>Store</h1>
                <div class="actions">
                    <div class="segmented" aria-label="Currency">
                        <button type="button" class="currency-button is-active" data-currency="usd">USD</button>
                        <button type="button" class="currency-button" data-currency="eur">EUR</button>
                        <button type="button" class="currency-button" data-currency="gbp">GBP</button>
                        <button type="button" class="currency-button" data-currency="dop">DOP</button>
                    </div>
                    <button type="button" class="bag-button" id="openBag">Bag <span id="bagCount">0</span></button>
                </div>
            </section>

            <section class="feature" aria-label="Upcoming concert">
                <div class="feature-image">
                    <img src="data:image/png;base64," alt="Luxury concert stage for Reny Renteria upcoming show">
                </div>
                <div class="feature-copy">
                    <div>
                        <span class="eyebrow">Upcoming Concert</span>
                        <h2>Reny Live · Panama</h2>
                        <div class="drop-strip" aria-label="Concert status">
                            <div>
                                <strong>Aug 24</strong>
                                <span>Date</span>
                            </div>
                            <div>
                                <strong>Panama</strong>
                                <span>City</span>
                            </div>
                            <div>
                                <strong>96</strong>
                                <span>Seats</span>
                            </div>
                        </div>
                    </div>
                    <div class="feature-price">
                        <div>
                            <strong data-price="concert">$42</strong>
                            <span>physical ticket · +420 pts</span>
                        </div>
                        <button type="button" class="button gold" data-buy="concert">Buy Tickets</button>
                    </div>
                </div>
            </section>

            <section class="market" aria-label="Royal's Exclusives catalog">
                <h2>Royal's Exclusives</h2>
                <div class="filters" role="tablist" aria-label="Product filters">
                    <button type="button" class="filter is-active" data-filter="all" role="tab" aria-selected="true">All</button>
                    <button type="button" class="filter" data-filter="digital" role="tab" aria-selected="false">Digital</button>
                    <button type="button" class="filter" data-filter="drop" role="tab" aria-selected="false">Drops</button>
                    <button type="button" class="filter" data-filter="physical" role="tab" aria-selected="false">Merch</button>
                    <button type="button" class="filter" data-filter="subscription" role="tab" aria-selected="false">Pass</button>
                </div>
            </section>

            <section class="product-grid" aria-label="Store products">
                <article class="product-card" data-category="drop physical" data-product="crown">
                    <button type="button" class="product-button" data-detail="crown">
                        <span class="visual hero-crop" aria-hidden="true"></span>
                        <span class="product-meta">
                            <span class="product-line">
                                <h3>Crown Jacket No. 01</h3>
                                <strong data-price="crown">$380</strong>
                            </span>
                            <span class="chips">
                                <span class="chip gold" id="dropChip">12 of 50</span>
                                <span class="chip">Drop</span>
                                <span class="chip">+950 pts</span>
                                <span class="chip">Royal early</span>
                            </span>
                        </span>
                    </button>
                </article>

                <article class="product-card" data-category="digital" data-product="deluxe">
                    <button type="button" class="product-button" data-detail="deluxe">
                        <span class="visual album" aria-hidden="true"></span>
                        <span class="product-meta">
                            <span class="product-line">
                                <h3>Deluxe Digital Album</h3>
                                <strong data-price="deluxe">$24</strong>
                            </span>
                            <span class="chips">
                                <span class="chip">Digital</span>
                                <span class="chip gold">Instant</span>
                                <span class="chip">+240 pts</span>
                                <span class="chip">No pass</span>
                            </span>
                        </span>
                    </button>
                </article>

                <article class="product-card" data-category="digital" data-product="singles">
                    <button type="button" class="product-button" data-detail="singles">
                        <span class="visual pack" aria-hidden="true"></span>
                        <span class="product-meta">
                            <span class="product-line">
                                <h3>Singles / Digital Pack</h3>
                                <strong data-price="singles">$8</strong>
                            </span>
                            <span class="chips">
                                <span class="chip">Digital</span>
                                <span class="chip gold">Unlocked</span>
                                <span class="chip">+80 pts</span>
                                <span class="chip">No pass</span>
                            </span>
                        </span>
                    </button>
                </article>

                <article class="product-card" data-category="subscription" data-product="royal">
                    <button type="button" class="product-button" data-detail="royal">
                        <span class="visual pass" aria-hidden="true"></span>
                        <span class="product-meta">
                            <span class="product-line">
                                <h3>Royal Pass</h3>
                                <strong data-price="royal">$19/mo</strong>
                            </span>
                            <span class="chips">
                                <span class="chip">Subscription</span>
                                <span class="chip gold">48h early</span>
                                <span class="chip">+190 pts</span>
                                <span class="chip">Shop buy</span>
                            </span>
                        </span>
                    </button>
                </article>

                <article class="product-card" data-category="physical" data-product="merch">
                    <button type="button" class="product-button" data-detail="merch">
                        <span class="visual merch" aria-hidden="true"></span>
                        <span class="product-meta">
                            <span class="product-line">
                                <h3>Studio Merch</h3>
                                <strong data-price="merch">$48</strong>
                            </span>
                            <span class="chips">
                                <span class="chip">Physical</span>
                                <span class="chip gold">In stock</span>
                                <span class="chip">+120 pts</span>
                                <span class="chip">No pass</span>
                            </span>
                        </span>
                    </button>
                </article>

                <article class="product-card" data-category="drop physical" data-product="print">
                    <button type="button" class="product-button" data-detail="print">
                        <span class="visual print" aria-hidden="true"></span>
                        <span class="product-meta">
                            <span class="product-line">
                                <h3>Numbered Art Print</h3>
                                <strong data-price="print">$86</strong>
                            </span>
                            <span class="chips">
                                <span class="chip gold">31 of 100</span>
                                <span class="chip">Drop</span>
                                <span class="chip">+220 pts</span>
                                <span class="chip">Royal early</span>
                            </span>
                        </span>
                    </button>
                </article>
            </section>

            <section class="events" aria-label="Upcoming events">
                <div class="section-title">
                    <h2>Events</h2>
                    <span>Digital + physical</span>
                </div>
                <div class="event-grid">
                    <article class="event-card">
                        <img class="event-photo" src="data:image/jpeg;base64," alt="Reny Live Studio Night concert stage">
                        <div class="event-content">
                            <span class="event-kicker">Live show</span>
                            <h3>Reny Live · Studio Night</h3>
                            <div class="event-meta">
                                <span><b>Date</b> Aug 24, 2026</span>
                                <span><b>Place</b> Panama City, Panama</span>
                            </div>
                            <div class="event-actions">
                                <button type="button" class="button gold" data-buy="concert">Buy ticket</button>
                            </div>
                        </div>
                    </article>
                    <article class="event-card is-digital">
                        <img class="event-photo" src="data:image/jpeg;base64," alt="Making The Deluxe Album livestream studio">
                        <div class="event-content">
                            <span class="event-kicker">Digital event</span>
                            <h3>Making The Deluxe Album</h3>
                            <div class="event-meta">
                                <span><b>Date</b> Jul 12, 2026</span>
                                <span><b>Place</b> Royal Stream</span>
                            </div>
                            <div class="event-actions">
                                <button type="button" class="button light" data-rsvp="Making The Deluxe Album">RSVP</button>
                            </div>
                        </div>
                    </article>
                    <article class="event-card is-listening">
                        <img class="event-photo" src="data:image/jpeg;base64," alt="Deluxe Preview Session listening room">
                        <div class="event-content">
                            <span class="event-kicker">Listening session</span>
                            <h3>Deluxe Preview Session</h3>
                            <div class="event-meta">
                                <span><b>Date</b> Sep 06, 2026</span>
                                <span><b>Place</b> Deluxe Listening Room</span>
                            </div>
                            <div class="event-actions">
                                <button type="button" class="button light" data-buy="listening">Buy ticket</button>
                            </div>
                        </div>
                    </article>
                </div>
            </section>
        </main>
    </div>

    <nav class="mobile-bottom-nav" aria-label="Mobile navigation">
        <a href="/"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M9 18V5l12-2v13"></path><circle cx="6" cy="18" r="3"></circle><circle cx="18" cy="16" r="3"></circle></svg><span class="sr-only">Music</span></a>
        <a href="/videos"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M15 10l5 3-5 3v-6Z"></path><rect x="3" y="5" width="18" height="14" rx="2"></rect></svg><span class="sr-only">Videos</span></a>
        <a href="/photos"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="5" width="18" height="14" rx="2"></rect><circle cx="8" cy="10" r="2"></circle><path d="m21 15-5-5L5 19"></path></svg><span class="sr-only">Photos</span></a>
        <a href="/community"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v8Z"></path></svg><span class="sr-only">Community</span></a>
        <a class="is-active" href="/store" aria-current="page"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4H6Z"></path><path d="M3 6h18"></path><path d="M16 10a4 4 0 0 1-8 0"></path></svg><span class="sr-only">Store</span></a>
    </nav>

    <section class="modal-layer" id="detailLayer" hidden inert>
        <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="detailTitle">
            <div class="dialog-head">
                <h2 id="detailTitle">Product</h2>
                <button type="button" class="icon-button" data-close="detailLayer" aria-label="Close product details">×</button>
            </div>
            <div class="product-detail">
                <div id="detailVisual" class="detail-visual visual album" aria-hidden="true"></div>
                <div class="detail-copy">
                    <div>
                        <p id="detailText"></p>
                        <div class="detail-grid" id="detailGrid"></div>
                    </div>
                    <button type="button" class="button" id="detailBuy">Add to bag</button>
                </div>
            </div>
        </div>
    </section>

    <section class="modal-layer" id="bagLayer" hidden inert>
        <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="bagTitle">
            <div class="dialog-head">
                <h2 id="bagTitle">Checkout</h2>
                <button type="button" class="icon-button" data-close="bagLayer" aria-label="Close checkout">×</button>
            </div>
            <div class="checkout-grid">
                <div class="checkout-panel">
                    <h3>Step 1 · Bag</h3>
                    <div class="bag-list" id="bagList"></div>
                    <input class="email" id="emailField" type="email" value="fan@renyrenteria.com" aria-label="Receipt email">
                    <div class="total-row">
                        <span>Total</span>
                        <strong id="bagTotal">$0</strong>
                    </div>
                </div>
                <div class="checkout-panel">
                    <h3>Step 2 · Pay</h3>
                    <div class="payments" role="radiogroup" aria-label="Payment method">
                        <button type="button" class="is-active">Card</button>
                        <button type="button">PayPal</button>
                        <button type="button">Apple Pay</button>
                        <button type="button">Local</button>
                    </div>
                    <button type="button" class="button" id="completePurchase" style="width:100%; margin-top:18px;">Complete</button>
                </div>
            </div>
        </div>
    </section>

    <section class="modal-layer" id="certificateLayer" hidden inert>
        <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="certificateTitle">
            <div class="dialog-head">
                <h2 id="certificateTitle">Certificate</h2>
                <button type="button" class="icon-button" data-close="certificateLayer" aria-label="Close certificate">×</button>
            </div>
            <div class="certificate-card">
                <span class="eyebrow">Digital Certificate</span>
                <h3>Crown Jacket No. 01</h3>
                <p>Ownership recorded to profile. Receipt sent by email. Royal tier and points updated immediately.</p>
                <div class="certificate-meta">
                    <div>
                        <strong id="certificatePiece">#39 / 50</strong>
                        <span>Piece</span>
                    </div>
                    <div>
                        <strong>+950</strong>
                        <span>Points</span>
                    </div>
                    <div>
                        <strong>Royal</strong>
                        <span>Tier</span>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <div class="toast" id="toast" role="status" aria-live="polite"></div>

    <script>
        const prices = {
            crown: 380,
            deluxe: 24,
            singles: 8,
            royal: 19,
            merch: 48,
            print: 86,
            concert: 42,
            listening: 18,
        };

        const currencies = {
            usd: { label: "USD", symbol: "$", rate: 1, decimals: 0, position: "before" },
            eur: { label: "EUR", symbol: "€", rate: 0.92, decimals: 0, position: "before" },
            gbp: { label: "GBP", symbol: "£", rate: 0.78, decimals: 0, position: "before" },
            dop: { label: "DOP", symbol: "RD$", rate: 59, decimals: 0, position: "before" },
        };

        const products = {
            crown: {
                name: "Crown Jacket No. 01",
                type: "Drop",
                visual: "hero-crop",
                availability: "12 left of 50",
                points: "+950 pts",
                pass: "Royal Pass early access",
                access: "Certificate included",
                text: "Limited Royal exclusive piece with automatic numbering, certificate, and permanent profile ownership.",
            },
            deluxe: {
                name: "Deluxe Digital Album",
                type: "Digital",
                visual: "album",
                availability: "Instant access",
                points: "+240 pts",
                pass: "No Royal Pass required",
                access: "Unlocks in profile",
                text: "Extended cuts, alternate versions, lyric annotations, visual zine, and documentary materials.",
            },
            singles: {
                name: "Singles / Digital Pack",
                type: "Digital",
                visual: "pack",
                availability: "Instant access",
                points: "+80 pts",
                pass: "No Royal Pass required",
                access: "Unlocks in profile",
                text: "Small digital packs for fans who want the new release without waiting for the full album cycle.",
            },
            royal: {
                name: "Royal Pass",
                type: "Subscription",
                visual: "pass",
                availability: "Active today",
                points: "+190 pts",
                pass: "Pass product",
                access: "Content lives in Royal Pass",
                text: "Monthly membership with exclusive songs, livestreams, community access, voting, and early drops.",
            },
            merch: {
                name: "Studio Merch",
                type: "Physical",
                visual: "merch",
                availability: "In stock",
                points: "+120 pts",
                pass: "No Royal Pass required",
                access: "Ships after checkout",
                text: "Minimal studio pieces designed as wearable objects, not generic tour merch.",
            },
            print: {
                name: "Numbered Art Print",
                type: "Drop",
                visual: "print",
                availability: "31 left of 100",
                points: "+220 pts",
                pass: "Royal Pass early access",
                access: "Certificate included",
                text: "A numbered visual companion to the current release and an entry point into Royal's Exclusives.",
            },
            concert: {
                name: "Reny Live · Panama",
                type: "Physical event",
                visual: "hero-crop",
                availability: "96 seats",
                points: "+420 pts",
                pass: "No Royal Pass required",
                access: "Ticket unlocks in profile",
                text: "Upcoming live concert ticket with instant receipt, profile update, and event access.",
            },
            listening: {
                name: "Deluxe Preview Session",
                type: "Physical event",
                visual: "album",
                availability: "40 seats",
                points: "+180 pts",
                pass: "Royal Pass early access",
                access: "Ticket unlocks in profile",
                text: "Intimate listening room preview for the next deluxe release.",
            },
        };

        let currency = "usd";
        let bag = [];
        let focusedBeforeModal = null;
        let activeProduct = null;
        let dropLeft = 12;
        let nextPiece = 39;
        const toast = document.getElementById("toast");
        const bagCount = document.getElementById("bagCount");
        const bagList = document.getElementById("bagList");
        const bagTotal = document.getElementById("bagTotal");
        const tierLabel = document.getElementById("tierLabel");

        function money(value, suffix = "") {
            const current = currencies[currency];
            const converted = value * current.rate;
            const amount = converted.toLocaleString("en-US", {
                maximumFractionDigits: current.decimals,
                minimumFractionDigits: current.decimals,
            });
            return current.position === "before"
                ? `${current.symbol}${amount}${suffix}`
                : `${amount} ${current.symbol}${suffix}`;
        }

        function updatePrices() {
            document.querySelectorAll("[data-price]").forEach((node) => {
                const key = node.dataset.price;
                const suffix = key === "royal" ? "/mo" : "";
                node.textContent = money(prices[key], suffix);
            });
        }

        function showToast(message) {
            toast.textContent = message;
            toast.classList.add("is-visible");
            clearTimeout(showToast.timer);
            showToast.timer = setTimeout(() => toast.classList.remove("is-visible"), 2200);
        }

        function setInert(layer, inert) {
            if (inert) {
                layer.setAttribute("inert", "");
            } else {
                layer.removeAttribute("inert");
            }
        }

        function openLayer(id) {
            focusedBeforeModal = document.activeElement;
            const layer = document.getElementById(id);
            layer.hidden = false;
            setInert(layer, false);
            document.body.classList.add("is-locked");
            const focusTarget = layer.querySelector("button, [href], input, select, textarea, [tabindex]:not([tabindex='-1'])");
            focusTarget?.focus();
        }

        function closeLayer(id) {
            const layer = document.getElementById(id);
            layer.hidden = true;
            setInert(layer, true);
            document.body.classList.remove("is-locked");
            focusedBeforeModal?.focus();
        }

        function trapFocus(layer, event) {
            const focusable = [...layer.querySelectorAll("button, [href], input, select, textarea, [tabindex]:not([tabindex='-1'])")]
                .filter((node) => !node.disabled && node.offsetParent !== null);
            if (!focusable.length) return;
            const first = focusable[0];
            const last = focusable[focusable.length - 1];
            if (event.shiftKey && document.activeElement === first) {
                event.preventDefault();
                last.focus();
            } else if (!event.shiftKey && document.activeElement === last) {
                event.preventDefault();
                first.focus();
            }
        }

        function updateDrop() {
            document.getElementById("dropChip").textContent = `${dropLeft} of 50`;
            products.crown.availability = `${dropLeft} left of 50`;
        }

        function renderBag() {
            bagCount.textContent = bag.length;
            if (!bag.length) {
                bagList.innerHTML = `<div class='bag-item'><span>Bag is empty</span><strong>${money(0)}</strong></div>`;
                bagTotal.textContent = money(0);
                return;
            }

            bagList.replaceChildren();
            let total = 0;
            bag.forEach((key) => {
                total += prices[key];
                const item = document.createElement("div");
                item.className = "bag-item";
                const name = document.createElement("span");
                name.textContent = products[key].name;
                const price = document.createElement("strong");
                price.textContent = money(prices[key], key === "royal" ? "/mo" : "");
                item.append(name, price);
                bagList.append(item);
            });
            bagTotal.textContent = money(total);
        }

        function addToBag(key) {
            bag.push(key);
            renderBag();
            showToast(`${products[key].name} added.`);
        }

        function openDetail(key) {
            activeProduct = key;
            const product = products[key];
            document.getElementById("detailTitle").textContent = product.name;
            document.getElementById("detailText").textContent = product.text;
            const visual = document.getElementById("detailVisual");
            visual.className = `detail-visual visual ${product.visual}`;
            const grid = document.getElementById("detailGrid");
            grid.replaceChildren();
            [
                [money(prices[key], key === "royal" ? "/mo" : ""), "Price"],
                [product.type, "Type"],
                [product.availability, "Availability"],
                [product.points, "Points"],
                [product.pass, "Royal Pass"],
                [product.access, "Access"],
            ].forEach(([value, label]) => {
                const cell = document.createElement("div");
                const strong = document.createElement("strong");
                const span = document.createElement("span");
                strong.textContent = value;
                span.textContent = label;
                cell.append(strong, span);
                grid.append(cell);
            });
            document.getElementById("detailBuy").textContent = key === "crown" ? "Checkout Drop" : "Add to bag";
            openLayer("detailLayer");
        }

        document.querySelectorAll(".currency-button").forEach((button) => {
            button.addEventListener("click", () => {
                currency = button.dataset.currency;
                document.querySelectorAll(".currency-button").forEach((node) => node.classList.toggle("is-active", node === button));
                updatePrices();
                renderBag();
            });
        });

        document.querySelectorAll(".filter").forEach((button) => {
            button.addEventListener("click", () => {
                const filter = button.dataset.filter;
                document.querySelectorAll(".filter").forEach((node) => {
                    const active = node === button;
                    node.classList.toggle("is-active", active);
                    node.setAttribute("aria-selected", String(active));
                });
                document.querySelectorAll(".product-card").forEach((card) => {
                    const visible = filter === "all" || card.dataset.category.split(" ").includes(filter);
                    card.hidden = !visible;
                });
            });
        });

        document.querySelectorAll("[data-detail]").forEach((button) => {
            button.addEventListener("click", () => openDetail(button.dataset.detail));
        });

        document.querySelectorAll("[data-buy]").forEach((button) => {
            button.addEventListener("click", () => {
                addToBag(button.dataset.buy);
                openLayer("bagLayer");
            });
        });

        document.querySelectorAll("[data-rsvp]").forEach((button) => {
            button.addEventListener("click", () => {
                showToast(`${button.dataset.rsvp} RSVP saved.`);
            });
        });

        document.getElementById("detailBuy").addEventListener("click", () => {
            if (activeProduct) {
                addToBag(activeProduct);
                closeLayer("detailLayer");
                openLayer("bagLayer");
            }
        });

        document.getElementById("openBag").addEventListener("click", () => {
            renderBag();
            openLayer("bagLayer");
        });

        document.querySelectorAll(".payments button").forEach((button) => {
            button.addEventListener("click", () => {
                document.querySelectorAll(".payments button").forEach((node) => node.classList.toggle("is-active", node === button));
            });
        });

        document.getElementById("completePurchase").addEventListener("click", () => {
            if (!bag.length) {
                showToast("Add a product first.");
                return;
            }
            const boughtCrown = bag.includes("crown");
            if (boughtCrown && dropLeft > 0) {
                document.getElementById("certificatePiece").textContent = `#${nextPiece} / 50`;
                dropLeft -= 1;
                nextPiece += 1;
                updateDrop();
            }
            tierLabel.textContent = bag.includes("royal") || boughtCrown ? "Royal" : "Updated";
            bag = [];
            renderBag();
            closeLayer("bagLayer");
            if (boughtCrown) {
                openLayer("certificateLayer");
            } else {
                showToast("Receipt sent. Profile updated.");
            }
        });

        document.querySelectorAll("[data-close]").forEach((button) => {
            button.addEventListener("click", () => closeLayer(button.dataset.close));
        });

        document.addEventListener("keydown", (event) => {
            const openLayerId = ["certificateLayer", "bagLayer", "detailLayer"].find((id) => {
                return !document.getElementById(id).hidden;
            });
            if (!openLayerId) return;
            const layer = document.getElementById(openLayerId);
            if (event.key === "Tab") {
                trapFocus(layer, event);
            }
            if (event.key === "Escape") {
                closeLayer(openLayerId);
            }
        });

        updatePrices();
        renderBag();
        updateDrop();
    </script>
</body>
</html>
